import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** A precondition the work waits on, from whom, since when and by when it is needed: the waiting-on ledger, whose status is computed from its dates */
export interface WaitingRow {
  /** What identifies the wait */
  readonly waitingId: string;
  /** What is waited on */
  readonly what: string;
  /** Who must give it */
  readonly onWhom: string;
  /** Since when it is waited on */
  readonly since: Timestamp;
  /** By when it is needed */
  readonly neededBy: Timestamp | null;
  /** Where it is */
  readonly status: "open" | "resolved" | "cancelled";
  /** When it came */
  readonly resolvedAt: Timestamp | null;
}

/** What an insert into waiting takes: what the database fills may be left out. */
export interface WaitingInsert {
  readonly waitingId: string;
  readonly what: string;
  readonly onWhom: string;
  readonly since: Timestamp;
  readonly neededBy?: Timestamp | null;
  readonly status: "open" | "resolved" | "cancelled";
  readonly resolvedAt?: Timestamp | null;
}

/** The key of a row of waiting. */
export type WaitingKey = { readonly waitingId: string };

/** A precondition the work waits on, from whom, since when and by when it is needed: the waiting-on ledger, whose status is computed from its dates */
export const waiting = defineTable<WaitingRow, WaitingInsert, "waiting">({
  alias: "waiting",
  name: "waiting",
  columns: {
    waitingId: "waiting_id",
    what: "what",
    onWhom: "on_whom",
    since: "since",
    neededBy: "needed_by",
    status: "status",
    resolvedAt: "resolved_at",
  },
  primaryKey: ["waitingId"],
});

/** A decision that shaped the platform, with its context, what was decided and what follows from it, so that a later person finds out why and not only what */
export interface DecisionRow {
  /** What identifies the decision */
  readonly decisionId: string;
  /** What was decided, in a line */
  readonly title: string;
  /** What made it necessary */
  readonly context: string;
  /** What was decided */
  readonly outcome: string;
  /** What follows from it */
  readonly consequences: string | null;
  /** Where it is */
  readonly status: "proposed" | "accepted" | "rejected" | "superseded";
  /** Who decided */
  readonly decidedBy: string | null;
  /** When */
  readonly decidedAt: Timestamp | null;
  /** The decision this one replaced */
  readonly supersedesDecisionId: string | null;
}

/** What an insert into decision takes: what the database fills may be left out. */
export interface DecisionInsert {
  readonly decisionId: string;
  readonly title: string;
  readonly context: string;
  readonly outcome: string;
  readonly consequences?: string | null;
  readonly status: "proposed" | "accepted" | "rejected" | "superseded";
  readonly decidedBy?: string | null;
  readonly decidedAt?: Timestamp | null;
  readonly supersedesDecisionId?: string | null;
}

/** The key of a row of decision. */
export type DecisionKey = { readonly decisionId: string };

/** A decision that shaped the platform, with its context, what was decided and what follows from it, so that a later person finds out why and not only what */
export const decision = defineTable<DecisionRow, DecisionInsert, "decision">({
  alias: "decision",
  name: "decision",
  columns: {
    decisionId: "decision_id",
    title: "title",
    context: "context",
    outcome: "outcome",
    consequences: "consequences",
    status: "status",
    decidedBy: "decided_by",
    decidedAt: "decided_at",
    supersedesDecisionId: "supersedes_decision_id",
  },
  primaryKey: ["decisionId"],
  foreignKeys: [
    { columns: ["supersedesDecisionId"], references: "decision", referencesColumns: ["decisionId"] },
  ],
});

